// 用一组「信号」给单体打「是否该拆」的分：部署频率、团队人数、跨模块耦合
function splitScore({ deploysPerWeek, teamSize, coupling }) {
  return deploysPerWeek * 0.5 + teamSize * 0.8 + coupling * 4;
}

const mono = { deploysPerWeek: 1, teamSize: 4, coupling: 1 };
const growing = { deploysPerWeek: 20, teamSize: 25, coupling: 7 };

console.log(splitScore(mono).toFixed(1));
console.log(splitScore(growing).toFixed(1));
console.log(splitScore(growing) > 15 ? "建议拆分" : "维持单体");
